export type SeverityLevel = "Verbose" | "Information" | "Warning" | "Error" | "Critical";

export interface AzureTraceEvent {
  readonly timestamp: string;
  readonly operationId: string;
  readonly operationParentId?: string;
  readonly spanId: string;
  readonly cloudRole: string;
  readonly message: string;
  readonly severityLevel: SeverityLevel;
  readonly customDimensions?: Readonly<Record<string, string>>;
}

export interface AzureMetricPoint {
  readonly timestamp: string;
  readonly metricName: string;
  readonly value: number;
  readonly count: number;
  readonly min: number;
  readonly max: number;
  readonly resourceId: string;
  readonly dimensions?: Readonly<Record<string, string>>;
}

export interface AzureDependencySpan {
  readonly timestamp: string;
  readonly operationId: string;
  readonly spanId: string;
  readonly target: string;
  readonly type: "SQL" | "HTTP" | "AzureQueue" | "CosmosDB" | "BlobStorage";
  readonly durationMs: number;
  readonly success: boolean;
  readonly resultCode: string;
  readonly commandName?: string;
}

export interface TelemetryDataset {
  readonly traces: readonly AzureTraceEvent[];
  readonly metrics: readonly AzureMetricPoint[];
  readonly dependencies: readonly AzureDependencySpan[];
}

export interface AnomalyFinding {
  readonly id: string;
  readonly resource: string;
  readonly metricOrEventType: string;
  readonly observedValue: number | string;
  readonly expectedThreshold: number | string;
  readonly severity: SeverityLevel;
  readonly detectedAt: string;
  readonly description: string;
}

export interface TraceGraphNode {
  readonly spanId: string;
  readonly operationId: string;
  readonly cloudRole: string;
  readonly durationMs?: number;
  readonly isError: boolean;
  readonly errorMessage?: string;
  readonly children: readonly TraceGraphNode[];
}

export interface DiagnosticReport {
  readonly incidentId: string;
  readonly incidentSummary: string;
  readonly generatedAt: string;
  readonly anomaliesDetected: readonly AnomalyFinding[];
  readonly rootCauseSpan?: AzureDependencySpan | AzureTraceEvent;
  readonly impactedEndpoints: readonly string[];
  readonly remediationRecommendations: readonly string[];
}

